class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        seen = [False] * (n + 1)
        cur, step = 1, k
        seen[1] = True
        while True:
            cur = (cur - 1 + step) % n + 1
            if seen[cur]:
                break
            seen[cur] = True
            step += k
        return [i for i in range(1, n + 1) if not seen[i]]

