class Solution {
public:
    vector<int> circularGameLosers(int n, int k) {
        vector<bool> seen(n + 1, false);
        int cur = 1, step = k;
        seen[1] = true;
        while (true) {
            cur = (cur - 1 + step) % n + 1;
            if (seen[cur]) break;
            seen[cur] = true;
            step += k;
        }
        vector<int> ans;
        for (int i = 1; i <= n; i++) if (!seen[i]) ans.push_back(i);
        return ans;
    }
};

