class Solution {
    public int[] circularGameLosers(int n, int k) {
        boolean[] seen = new boolean[n + 1];
        int cur = 1, step = k;
        seen[1] = true;
        while (true) {
            cur = (cur - 1 + step) % n + 1;
            if (seen[cur]) break;
            seen[cur] = true;
            step += k;
        }
        int[] tmp = new int[n];
        int m = 0;
        for (int i = 1; i <= n; i++) if (!seen[i]) tmp[m++] = i;
        return Arrays.copyOf(tmp, m);
    }
}

